area.action:
for(x in 2...26) setTile(x, 0, "empty"); for(x in 25...28) setTile(x, 1, "empty"); for(x in 1...9) setTile(x, 15, "empty");
for(x in 8...15) setTile(x, 14, "empty"); for(x in 14...28) setTile(x, 15, "empty"); for(y in 2...15) setTile(27, y, "empty");
for(y in 1...6) setTile(1, y, "empty"); for(y in 5...11) setTile(3, y, "empty"); for(y in 10...12) setTile(2, y, "empty");
for(y in 11...16) setTile(1, y, "empty"); setTile(2, 1, "empty"); setTile(2, 5, "empty");
area.floodFill(7, 7, BACK_LAYER, area.addTileIndex("empty"));

procedure.action:
setGlobal("originalPlayer", player); setGlobal("originalArea", player.area); setGlobal("points", 750);
		var map = new StringMap(); map.set("dragomech", 1); setGlobal("killCounts", map);
		changePlayer("player.colosseum", false); player.inventory.addItems(getItem("coral_cod"), 10); player.inventory.addItems(getItem("cake"), 30); player.inventory.addItems(getItem("missile"), 20);
		player.inventory.addItems(getItem("battery"), 4); player.inventory.addItems(getItem("rocket_launcher"), 1);
		player.stats.get("spellcast").permaBuff(5); player.stats.get("speed").permaBuff(4); player.stats.get("health").permaBuff(100); player.restoreHealth();
